#include <bits/stdc++.h>
using namespace std;

#define N 16
#define MOD 998244353
#define ll long long
#define rep(i, n) for(int i = 0; i < n; ++i)

ll modpow(ll x, ll k) {
	ll re = 1;
	while (k > 0) {
		if (k & 1)re = (re*x) % MOD;
		k = (k >> 1);
		x = (x*x) % MOD;
	}
	return re;
}

ll rev(ll x) { return modpow(x, MOD - 2); }

int main() {
	int n;
	ll m;
	ll a[N], b[N];
	ll c[N];
	ll d[(1 << N)], p[(1 << N)];
	ll x, y;
	ll ans = 0;

	cin >> n >> m;
	d[0] = 1LL;
	p[0] = 0LL;

	rep(i, n) {
		cin >> a[i] >> b[i];
		b[i]++;
		x = (MOD - modpow(a[i], b[i])) % MOD;
		rep(j, (1 << i)) {
			d[(1 << i) + j] = (d[j] * x) % MOD;
			p[(1 << i) + j] = p[j] + b[i];
		}
	}

	rep(i, n) {
		x = rev(a[i]);
		c[i] = 1LL;
		rep(j, n) {
			if (j != i) {
				y = (a[j] * x) % MOD;
				c[i] = (c[i] * (MOD + 1 - y)) % MOD;
			}
		}
		c[i] = rev(c[i]);
	}

	rep(i, (1 << n)) {
		if (p[i] <= m) {
			x = 0;
			rep(j, n) {
				x = (x + (modpow(a[j], m - p[i])*c[j])) % MOD;
			}
			ans = (ans + (x*d[i])) % MOD;
		}
	}

	cout << ans << endl;
	return 0;
}
